const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function card(c){return `<article class="company-card"><div class="company-top"><div class="company-monogram" style="--brand-bg:${c.bg};--brand-color:${c.color}">${c.initials}</div><div><h3>${c.name}</h3><p class="company-location">${c.cityLabel} · საქართველო</p></div></div><p class="company-description">${c.description}</p><div class="tags">${c.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="company-bottom"><span class="availability">სადემონსტრაციო პროფილი</span><button class="details-button" data-company="${c.id}">ნახე დეტალები ↗</button></div></article>`}
const grid=document.querySelector('#category-grid');if(grid)grid.innerHTML=categories.map(c=>`<a class="category-card" href="/categories/?type=${c.id}"><span class="category-icon"><svg viewBox="0 0 26 26" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[c.id]}</svg></span><span class="category-arrow" aria-hidden="true">↗</span><h3>${c.title}</h3><p>${c.sub}</p></a>`).join('');
const featured=document.querySelector('#featured-companies');if(featured)featured.innerHTML=companies.slice(0,3).map(card).join('');
document.querySelector('.nav-home')?.classList.add('active');
