function showCompany(id){const c=companies.find(c=>c.id===id);if(!c)return;document.querySelector('#detail-content').innerHTML=`<span class="section-kicker">სადემონსტრაციო კომპანია</span><div class="detail-heading"><div class="company-monogram" style="--brand-bg:${c.bg};--brand-color:${c.color}">${c.initials}</div><div><h2 id="detail-title">${c.name}</h2><span class="company-location">${c.cityLabel} · საქართველო</span></div></div><p>${c.description}</p><div class="detail-meta"><div><small>მომსახურების ტერიტორია</small>${c.area}</div><div><small>საკომუნიკაციო ენა</small>${c.languages}</div></div><section class="detail-section"><h3>რის შეთავაზება შეუძლია</h3><ul>${c.offer.map(x=>`<li>${x}</li>`).join('')}</ul></section><p class="form-note">ეს გამოგონილი სადემონსტრაციო პროფილია. ინფორმაცია აჩვენებს, როგორ გამოიყურება კომპანია MeetAny-ზე.</p><button class="button form-submit" data-intro="${c.id}">მოითხოვე გაცნობა ↗</button>`;document.querySelector('#detail-dialog').showModal();}
const cityNames={tbilisi:'თბილისი',batumi:'ბათუმი',kutaisi:'ქუთაისი'};
function validateFilters(input){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Invalid filters');const allowed=['q','type','city','language','sort'];if(Object.keys(input).some(k=>!allowed.includes(k)))throw Error('Unknown filter');for(const v of Object.values(input))if(typeof v!=='string')throw Error('Filter values must be strings');if(input.q?.length>200)throw Error('Query is too long');if(input.type&&!categories.some(c=>c.id===input.type))throw Error('Invalid category');if(input.city&&!cityNames[input.city])throw Error('Invalid city');if(input.language&&!['ka','en'].includes(input.language))throw Error('Invalid language');if(input.sort&&!['relevance','name'].includes(input.sort))throw Error('Invalid sort');return {q:'',type:'',city:'',language:'',sort:'relevance',...input};}
function readFilters(){const p=new URLSearchParams(location.search);const data={};for(const k of ['q','type','city','language','sort']){const value=p.get(k);if(value)data[k]=value.slice(0,200);}try{return validateFilters(data)}catch{return validateFilters({q:data.q||''})}}
let filters=readFilters();
const stopWords=['ვეძებ','მინდა','მჭირდება','და','ან','საჭიროა','ბიზნესისთვის','სანდო'];
function getResults(f){const terms=f.q.toLocaleLowerCase().split(/\s+/).filter(x=>x&&!stopWords.includes(x)).map(x=>x.replace(/(ისთვის|ებში|ების|ებს|ის|ს)$/u,''));const matches=companies.filter(c=>{if(f.type&&c.type!==f.type)return false;if(f.city&&!c.area.includes(cityNames[f.city])&&!c.area.includes('მთელი საქართველო'))return false;if(f.language==='en'&&!c.languages.includes('ინგლისური'))return false;const words=(c.name+' '+c.description+' '+c.words+' '+c.tags.join(' ')).toLocaleLowerCase().split(/\s+/);return !terms.length||terms.every(t=>words.some(w=>w.includes(t)));});if(f.sort==='name')matches.sort((a,b)=>a.name.localeCompare(b.name));return matches;}
function setFilters(next,{push=true}={}){filters=validateFilters({...filters,...next});const url=new URL(location.href);url.search='';for(const [k,v] of Object.entries(filters))if(v&&!(k==='sort'&&v==='relevance'))url.searchParams.set(k,v);if(push)history.pushState({},'',url);else history.replaceState({},'',url);renderResults();return getResults(filters);}
function renderResults(){const grid=document.querySelector('#results-grid');if(!grid)return;document.querySelectorAll('input[name="type"]').forEach(x=>x.checked=x.value===filters.type);document.querySelector('#city-filter').value=filters.city;document.querySelector('#language-filter').value=filters.language;document.querySelector('#sort-filter').value=filters.sort;document.querySelector('#catalog-query').value=filters.q;const category=categories.find(c=>c.id===filters.type);document.querySelector('#catalog-title').textContent=category?category.title:'იპოვე შენი პარტნიორი';document.title=(category?category.title:'კატეგორიები და კომპანიები')+' — MeetAny';const results=getResults(filters);document.querySelector('#result-count').innerHTML=`<strong>${results.length} კომპანია</strong> <span>· დემო კატალოგი</span>`;const chips=[filters.q&&['q',filters.q],category&&['type',category.title],filters.city&&['city',cityNames[filters.city]],filters.language&&['language',filters.language==='en'?'ინგლისური':'ქართული']].filter(Boolean);document.querySelector('#active-filters').innerHTML=chips.map(([k,v])=>`<button class="filter-chip" data-remove-filter="${k}" aria-label="ფილტრის წაშლა: ${esc(v)}">${esc(v)} ×</button>`).join('');grid.innerHTML=results.length?results.map(card).join(''):`<div class="empty-state"><span class="category-icon" style="margin:0 auto 20px">⌕</span><h2>ამ პირობებით კომპანია ვერ მოიძებნა</h2><p>სცადე სხვა საძიებო სიტყვა, გაასუფთავე ფილტრები ან შექმენი შენი მოთხოვნა.</p><div class="form-actions"><button class="button button-outline" data-reset>ფილტრების გასუფთავება</button><button class="button" data-action="request">შექმენი მოთხოვნა</button></div></div>`;}
if(document.querySelector('#results-grid')){document.querySelector('.nav-home').classList.remove('active');document.querySelector('.nav-categories').classList.add('active');document.querySelector('#type-options').innerHTML=[{id:'',title:'ყველა კატეგორია'},...categories].map(c=>`<label class="radio-option"><input type="radio" name="type" value="${c.id}">${c.title}</label>`).join('');document.querySelectorAll('input[name="type"]').forEach(x=>x.addEventListener('change',()=>setFilters({type:x.value})));document.querySelector('#city-filter').addEventListener('change',e=>setFilters({city:e.target.value}));document.querySelector('#language-filter').addEventListener('change',e=>setFilters({language:e.target.value}));document.querySelector('#sort-filter').addEventListener('change',e=>setFilters({sort:e.target.value}));document.querySelector('#catalog-search').addEventListener('submit',e=>{e.preventDefault();setFilters({q:document.querySelector('#catalog-query').value.trim()})});document.querySelector('#filter-toggle').addEventListener('click',e=>{const open=document.querySelector('#filters').classList.toggle('is-open');e.currentTarget.setAttribute('aria-expanded',String(open));});window.addEventListener('popstate',()=>{filters=readFilters();renderResults()});renderResults();}
let requestDraft={};let lastDraft=null;
function openRequest(companyId){const company=companies.find(c=>c.id===companyId);document.querySelector('#detail-dialog').close();const draft=requestDraft[companyId||'general']||{};document.querySelector('#form-content').innerHTML=`<span class="section-kicker">${company?'საქმიანი გაცნობა':'ბიზნესმოთხოვნა'}</span><h2 id="form-title">${company?company.name+' — გაცნობა':'რას ეძებს შენი ბიზნესი?'}</h2><p>მოკლედ აღწერე შენი მიზანი და თანამშრომლობის პირობები.</p><form id="intro-form"><div class="field"><label for="request-text">რა გჭირდება? *</label><textarea id="request-text" name="need" required minlength="10" maxlength="2000" placeholder="მაგალითად: ვეძებ სასტუმროსთვის თეთრეულის მომწოდებელს თბილისში.">${esc(draft.need||filters.q||'')}</textarea></div><div class="field"><label for="request-city">მომსახურების ადგილი *</label><input id="request-city" name="city" required maxlength="100" value="${esc(draft.city||cityNames[filters.city]||'')}" placeholder="მაგალითად: თბილისი"></div><div class="field"><label for="request-name">შენი სახელი / კომპანია *</label><input id="request-name" name="name" required maxlength="120" value="${esc(draft.name||'')}" autocomplete="organization" placeholder="სახელი ან კომპანიის დასახელება"></div><div class="field"><label for="request-email">ელფოსტა *</label><input id="request-email" type="email" name="email" required maxlength="200" value="${esc(draft.email||'')}" autocomplete="email" placeholder="name@company.ge"></div><p class="form-note">საცდელი რეჟიმი: მოთხოვნა არ იგზავნება და სერვერზე არ ინახება. შეგიძლია მოამზადო და ჩამოტვირთო მისი ტექსტი.</p><button class="button form-submit" type="submit">მოთხოვნის მომზადება ↗</button></form>`;const form=document.querySelector('#intro-form');form.addEventListener('input',()=>{requestDraft[companyId||'general']=Object.fromEntries(new FormData(form));});form.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));if(!data.need.trim()||!data.city.trim()||!data.name.trim()){form.querySelector('textarea').setCustomValidity('შეავსე მოთხოვნა და აუცილებელი ველები.');form.reportValidity();return;}lastDraft={...data,company:company?.name||'პარტნიორი შესარჩევია'};document.querySelector('#form-content').innerHTML=`<div class="success-icon">✓</div><h2 id="form-title">მოთხოვნა მომზადებულია</h2><p>${esc(lastDraft.company)}</p><p style="white-space:pre-wrap">${esc(data.need)}</p><p class="form-note">ეს მოთხოვნის მონახაზია — კომპანიასთან არ გაგზავნილა. ჩამოტვირთე ტექსტი შენს მოწყობილობაზე.</p><div class="form-actions"><button class="button" data-action="download">ტექსტის ჩამოტვირთვა ↓</button><button class="button button-outline" data-close>დასრულება</button></div>`;});form.querySelector('textarea').addEventListener('input',e=>e.target.setCustomValidity(''));document.querySelector('#form-dialog').showModal();}
function openCompanyForm(){document.querySelector('#form-content').innerHTML=`<span class="section-kicker">შენი კომპანია MeetAny-ზე</span><h2 id="form-title">კომპანიის დამატება</h2><p>მოამზადე შენი კომპანიის პროფილის მოკლე ვერსია.</p><form id="company-form"><div class="field"><label for="company-name">კომპანიის დასახელება *</label><input id="company-name" name="name" required maxlength="80"></div><div class="field"><label for="company-offer">რას სთავაზობ ბიზნესებს? *</label><textarea id="company-offer" name="offer" required minlength="10" maxlength="1500"></textarea></div><div class="field"><label for="company-area">მომსახურების ტერიტორია *</label><input id="company-area" name="area" required maxlength="100" placeholder="მაგალითად: მთელი საქართველო"></div><p class="form-note">საცდელი რეჟიმი: პროფილი საჯაროდ არ გამოქვეყნდება. შეგიძლია ნახო და ჩამოტვირთო მისი ტექსტი.</p><button class="button form-submit" type="submit">პროფილის წინასწარი ნახვა ↗</button></form>`;document.querySelector('#company-form').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));lastDraft={profile:true,...data};document.querySelector('#form-content').innerHTML=`<span class="section-kicker">პროფილის მონახაზი</span><h2 id="form-title">${esc(data.name)}</h2><p style="white-space:pre-wrap">${esc(data.offer)}</p><div class="detail-meta"><div><small>მომსახურების ტერიტორია</small>${esc(data.area)}</div></div><p class="form-note">პროფილი არ გამოქვეყნებულა. ეს ტექსტის წინასწარი ვერსიაა.</p><button class="button form-submit" data-action="download">პროფილის ტექსტის ჩამოტვირთვა ↓</button>`;});document.querySelector('#form-dialog').showModal();}
document.addEventListener('click',e=>{if(e.target.closest('[data-reset]'))setFilters({q:'',type:'',city:'',language:'',sort:'relevance'});const remove=e.target.closest('[data-remove-filter]');if(remove)setFilters({[remove.dataset.removeFilter]:''});const intro=e.target.closest('[data-intro]');if(intro)openRequest(intro.dataset.intro);const action=e.target.closest('[data-action]')?.dataset.action;if(action==='request')openRequest();if(action==='add-company')openCompanyForm();if(action==='download'&&lastDraft){const d=lastDraft;const text=d.profile?`MeetAny — კომპანიის მონახაზი\n\n${d.name}\n${d.offer}\n\nტერიტორია: ${d.area}\n\nსაცდელი ვერსია. პროფილი არ გამოქვეყნებულა.`:`MeetAny — გაცნობის მოთხოვნის მონახაზი\n\nმიმღები: ${d.company}\nგამომგზავნი: ${d.name}\nელფოსტა: ${d.email}\nადგილი: ${d.city}\n\n${d.need}\n\nსაცდელი ვერსია. მოთხოვნა არ გაგზავნილა.`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=d.profile?'MeetAny-profile.txt':'MeetAny-request.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
if(document.modelContext?.registerTool&&document.querySelector('#results-grid')){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'set_catalog_filters',title:'კომპანიების ძიება',description:'Set visible MeetAny demo catalog filters and return matching fictional companies. Does not contact companies.',inputSchema:{type:'object',properties:{q:{type:'string',maxLength:200},type:{type:'string',enum:['','suppliers','services','distributors','partners']},city:{type:'string',enum:['','tbilisi','batumi','kutaisi']},language:{type:'string',enum:['','ka','en']},sort:{type:'string',enum:['relevance','name']}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const f=validateFilters(input);const results=setFilters(f);return{count:results.length,companies:results.map(c=>({id:c.id,name:c.name,description:c.description})),demo:true}}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
